<section class="hero"><h1><?=e($heading)?></h1><p><?=e($description)?></p></section>
<section class="panel"><form class="filters" method="get"><label class="field">Biznesi / NRB<input name="q" value="<?=e($filters['q']??'')?>"></label><label class="field">Kodi NACE<input name="nace" value="<?=e($filters['nace']??'')?>"></label><label class="field">Klasifikimi<select name="classification"><option value="">Të gjitha</option><?php foreach(['UNCLASSIFIED'=>'Pa klasifikim','AUTO'=>'Automatik','MANUAL'=>'Manual','AMBIGUOUS'=>'I paqartë','NO_RELATION'=>'Pa relacion'] as $v=>$l):?><option value="<?=e($v)?>" <?=($filters['classification']??'')===$v?'selected':''?>><?=e($l)?></option><?php endforeach;?></select></label><label class="field">Statusi ATK<select name="atk_status"><option value="">Të gjitha</option><?php foreach(['ACTIVE'=>'Aktiv','DEACTIVATED'=>'Çaktivizuar','NEEDS_REVIEW'=>'Për shqyrtim'] as $v=>$l):?><option value="<?=e($v)?>" <?=($filters['atk_status']??'')===$v?'selected':''?>><?=e($l)?></option><?php endforeach;?></select></label><button>Kërko</button><a class="button secondary" href="<?=e(app_url('/admin/businesses/export.php?'.http_build_query($filters)))?>">Eksporto Excel</a></form></section>
<?php $returnQuery=http_build_query(array_merge($filters,['page'=>$result['page']]));?>
<div class="table-wrap"><table><thead><tr><th>Biznesi</th><th>NRB</th><th>Telefoni</th><th>Emaili</th><th>Menaxheri</th><th>Nr. njësive</th><th>NACE</th><th>Klasifikimi</th><th>Kategoria</th><th>Tarifa</th><th>ATK</th><th></th></tr></thead><tbody><?php foreach($result['rows'] as $row): $classification=$row['assignment_method']==='AUTO'?'Automatik':($row['assignment_method']==='MANUAL'?'Manual':((int)$row['candidate_count']>1?'I paqartë':((int)$row['candidate_count']===0?'Pa relacion':'Pa klasifikim')));?><tr><td><strong><?=e($row['legal_name'])?></strong></td><td><?=e($row['registration_number'])?></td><td><?=e($row['phone_number']??'—')?></td><td><?=e($row['email']??'—')?></td><td><?=e($row['manager_name']??'—')?></td><td><?=number_format((int)$row['unit_count'])?></td><td><?=e($row['arbk_nace_code'])?></td><td><span class="badge <?=e($row['assignment_method']??((int)$row['candidate_count']>1?'AMBIGUOUS':'UNCLASSIFIED'))?>"><?=e($classification)?></span></td><td><?=e($row['nace_category']??'—')?></td><td><?=$row['applied_tariff']!==null?number_format((float)$row['applied_tariff'],2).' €':'—'?></td><td><span class="badge <?=e($row['atk_status'])?>"><?=e($row['atk_status'])?></span></td><td><a class="button secondary" href="<?=e(app_url('/admin/businesses/view.php?id='.(int)$row['business_id'].'&return='.rawurlencode($returnQuery)))?>">Hap</a></td></tr><?php endforeach;?></tbody></table><?php if(!$result['rows']):?><div class="empty">Nuk u gjet asnjë biznes.</div><?php endif;?></div>
<div class="pagination"><span><?=number_format($result['total'])?> rezultate · Faqja <?=$result['page']?> / <?=$result['pages']?></span><span><?php if($result['page']>1):?><a href="?<?=e(http_build_query(array_merge($filters,['page'=>$result['page']-1])))?>">← Para</a><?php endif;?> <?php if($result['page']<$result['pages']):?><a href="?<?=e(http_build_query(array_merge($filters,['page'=>$result['page']+1])))?>">Pas →</a><?php endif;?></span></div>
